import { CalendarClock, CreditCard, Dumbbell, Info } from 'lucide-react';

import { cn } from '../../lib/utils';
import { NOTICE_KIND_LABELS, NOTICE_SEVERITY_STYLES, type PortalNotice } from '../../lib/memberPortal';
import { EmptyState } from '../ui/states';

const ICONS = {
  MEMBERSHIP: CalendarClock,
  PAYMENT: CreditCard,
  ROUTINE: Dumbbell,
  GYM: Info,
} as const;

/** Renders the notices generated by the backend (never client-side invented). */
export function NoticeList({ notices, emptyMessage }: { notices: PortalNotice[]; emptyMessage?: string }) {
  if (notices.length === 0) {
    return (
      <EmptyState
        title="No notices"
        message={emptyMessage ?? 'There is nothing that needs your attention right now.'}
      />
    );
  }

  return (
    <ul className="space-y-2">
      {notices.map((notice) => {
        const Icon = ICONS[notice.kind] ?? Info;
        return (
          <li
            key={notice.id}
            className={cn('rounded-lg border p-3 sm:p-4', NOTICE_SEVERITY_STYLES[notice.severity] ?? 'border-border')}
          >
            <div className="flex gap-3">
              <Icon className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" aria-hidden="true" />
              <div className="min-w-0">
                <p className="text-sm font-semibold">{notice.title}</p>
                <p className="mt-1 text-sm text-muted-foreground">{notice.message}</p>
                <p className="mt-1 text-xs text-muted-foreground">
                  {NOTICE_KIND_LABELS[notice.kind] ?? notice.kind}
                  {notice.date ? ` · ${new Date(notice.date).toLocaleDateString()}` : ''}
                </p>
              </div>
            </div>
          </li>
        );
      })}
    </ul>
  );
}
